#!/usr/bin/env bash
# src/agentic/k8s/kube.sh
# Reach a project's Kubernetes clusters through the kubeconfig `devbot init`
# generated for it. The generated file is named "<project>-<hash>.yaml" and its
# contexts come from the global `kubectl` catalogue, so neither is something a
# caller should have to reconstruct — that is what this command is for.
#
# Never use the plain ~/.kube/config for these clusters: its contexts are SSO
# exec contexts that expire, while the generated ones use the devbot profile.
set -euo pipefail

MODULE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=./functions.sh
source "${MODULE_DIR}/functions.sh"

_usage() {
  cat <<'EOF'
Usage:
  devbot kube env      [path]   Print KUBECONFIG for the project (no credentials)
  devbot kube contexts [path]   List the clusters this project may reach
  devbot kube run      [path] -- <kubectl args...>

`path` defaults to the current directory. The kubeconfig is generated by
`devbot init`; run `devbot reinit <path>` if it is missing.
EOF
}

# Resolve the generated files for a project. Sets PROJECT_DIR, PROJECT_CONFIG,
# READER, SPEC, SELECTION, KUBECONFIG_PATH and ENV_PATH.
_resolve() {
  local dir="${1:-.}" slug
  if [[ ! -d "${dir}" ]]; then
    _error "not a directory: ${dir}"
    return 1
  fi
  PROJECT_DIR="$(cd "${dir}" && pwd)"
  PROJECT_CONFIG="${PROJECT_DIR}/.devbot.project.jsonc"
  READER="${MODULE_DIR}/../../_shared/read_jsonc.py"

  SPEC="$(python3 "${READER}" "$(_devbot_global_config)" kubectl 2>/dev/null || true)"
  if [[ -z "${SPEC}" || "${SPEC}" == "null" ]]; then
    _error "no 'kubectl' node in $(_devbot_global_config)"
    return 1
  fi

  SELECTION="$(python3 "${READER}" "${PROJECT_CONFIG}" kubectl 2>/dev/null || true)"
  if [[ -z "${SELECTION}" || "${SELECTION}" == "null" ]]; then
    _error "${PROJECT_CONFIG} selects no clusters; add a 'kubectl' array"
    return 1
  fi

  slug="$(_project_slug)"
  KUBECONFIG_PATH="${HOME}/.kube/devbot/${slug}.yaml"
  ENV_PATH="${HOME}/.kube/devbot/${slug}.env"

  if [[ ! -f "${KUBECONFIG_PATH}" ]]; then
    _error "no generated kubeconfig at ${KUBECONFIG_PATH}; run: devbot reinit ${PROJECT_DIR}"
    return 1
  fi
}

cmd_env() {
  _resolve "${1:-.}" || return 1
  local current
  current="$(awk '/^current-context:/{print $2; exit}' "${KUBECONFIG_PATH}")"
  printf 'export KUBECONFIG=%q\n' "${KUBECONFIG_PATH}"
  printf 'export KUBE_CONTEXT=%q\n' "${current}"
  printf '# credentials: %s (sourced by devbot kube run)\n' "${ENV_PATH}"
}

cmd_contexts() {
  _resolve "${1:-.}" || return 1
  printf '%-10s %-18s %s\n' "NAME" "CONTEXT" "REGION"
  jq -r --argjson sel "${SELECTION}" \
    '.clusters[]
     | select(.name as $n | $sel | index($n))
     | [.name, .context, .region] | @tsv' <<<"${SPEC}" \
    | while IFS=$'\t' read -r name context region; do
      printf '%-10s %-18s %s\n' "${name}" "${context}" "${region}"
    done
}

cmd_run() {
  local project="."
  if [[ "${1:-}" != "--" && $# -gt 0 ]]; then
    project="$1"
    shift
  fi
  [[ "${1:-}" == "--" ]] && shift

  _resolve "${project}" || return 1

  if ! command -v kubectl >/dev/null 2>&1; then
    _error "kubectl is not on PATH"
    return 1
  fi
  if [[ ! -f "${ENV_PATH}" ]]; then
    _error "no credential file at ${ENV_PATH}; run: devbot reinit ${PROJECT_DIR}"
    return 1
  fi

  # Credentials are exported inside the subshell only, so they never reach the
  # caller's environment and are never printed. The target context goes to
  # stderr: the generated kubeconfig's current-context is whichever cluster the
  # catalogue lists first, which is production, so a mutating command must never
  # be fired without its target being visible.
  local current i
  current="$(awk '/^current-context:/{print $2; exit}' "${KUBECONFIG_PATH}")"
  local -a args=("$@")
  for ((i = 0; i < ${#args[@]}; i++)); do
    case "${args[i]}" in
      --context=*) current="${args[i]#--context=}" ;;
      --context) current="${args[i + 1]:-${current}}" ;;
    esac
  done
  printf 'kubectl context: %s\n' "${current}" >&2

  (
    set -a
    # shellcheck disable=SC1090
    source "${ENV_PATH}"
    set +a
    exec kubectl --kubeconfig "${KUBECONFIG_PATH}" "$@"
  )
}

main() {
  local cmd="${1:-}"
  if [[ $# -gt 0 ]]; then
    shift
  fi

  case "${cmd}" in
    env)
      cmd_env "${1:-.}"
      ;;
    contexts)
      cmd_contexts "${1:-.}"
      ;;
    run)
      cmd_run "$@"
      ;;
    "")
      _usage >&2
      exit 1
      ;;
    -h|--help|help)
      _usage
      ;;
    *)
      _error "unknown 'kube' subcommand: ${cmd}"
      _usage >&2
      exit 1
      ;;
  esac
}

main "$@"
